package dominoes

// Domino represents a single domino tile with two halves.
type Domino [2]int

// MakeChain computes a way to order the given dominoes so that they form a
// correct domino chain: the dots on one half of a stone match the dots on the
// neighboring half of an adjacent stone, and the dots on the halves of the
// stones which don't have a neighbor (the first and last stone) match each
// other. It reports whether such a chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	// A domino chain is an Eulerian circuit in the multigraph whose edges
	// are the dominoes. Such a circuit exists if and only if every vertex
	// has even degree and all vertices with non-zero degree belong to a
	// single connected component.

	type edgeRef struct {
		to    int
		index int
	}
	degree := map[int]int{}
	adj := map[int][]edgeRef{}
	for i, d := range input {
		degree[d[0]]++
		degree[d[1]]++
		adj[d[0]] = append(adj[d[0]], edgeRef{d[1], i})
		adj[d[1]] = append(adj[d[1]], edgeRef{d[0], i})
	}

	// Every vertex must have even degree.
	for _, deg := range degree {
		if deg%2 != 0 {
			return nil, false
		}
	}

	// All vertices must be in one connected component.
	var start int
	startSet := false
	for v := range adj {
		if !startSet {
			start = v
			startSet = true
		}
	}
	seen := map[int]bool{start: true}
	queue := []int{start}
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		for _, e := range adj[v] {
			if !seen[e.to] {
				seen[e.to] = true
				queue = append(queue, e.to)
			}
		}
	}
	for v := range adj {
		if !seen[v] {
			return nil, false
		}
	}

	// Find the Eulerian circuit with Hierholzer's algorithm.
	used := make([]bool, len(input))
	var circuit []int
	stack := []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		var next int
		found := false
		for _, e := range adj[v] {
			if !used[e.index] {
				used[e.index] = true
				next = e.to
				found = true
				break
			}
		}
		if !found {
			circuit = append(circuit, v)
			stack = stack[:len(stack)-1]
			continue
		}
		stack = append(stack, next)
	}

	// circuit is built in reverse; reverse it.
	for i, j := 0, len(circuit)-1; i < j; i, j = i+1, j-1 {
		circuit[i], circuit[j] = circuit[j], circuit[i]
	}

	// Sanity check; must hold given the pre-checks above.
	if len(circuit) != len(input)+1 || circuit[0] != circuit[len(circuit)-1] {
		return nil, false
	}

	// Orient each domino so that adjacent halves match.
	chain := make([]Domino, len(input))
	for i := range chain {
		chain[i] = Domino{circuit[i], circuit[i+1]}
	}
	return chain, true
}

